import os, base64, zlib
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
T = {'srv.py': '', 'fastpost.js': '', 'fastpost.css': ''}
def D(k): return zlib.decompress(base64.b64decode(T[k])).decode("utf-8")
if os.path.exists(P("static/js/fastpost.js")): raise SystemExit("[loi] da ap dung patch51 roi")
a = rd("app.py")
if "_probe_media" in a: raise SystemExit("[loi] da ap dung patch51 roi")
a = sub(a, "def parse_post_meta(", D("srv.py") + "def parse_post_meta(", "parse_post_meta")
w("app.py", a)
w("static/js/fastpost.js", D("fastpost.js"))
w("static/polish.css", rd("static/polish.css") + "\n" + D("fastpost.css"))
h = rd("templates/index.html")
h = sub(h, "</body>", '  <script src="/static/js/fastpost.js"></script>\n</body>', "index body")
w("templates/index.html", h)
print("[ok] patch51 xong: dang bai nhanh (video H.264 giu nguyen, anh nen truoc khi gui, hien phan tram)")
